// Package api implements the owner API defined in
// packages/api-spec/openapi.yaml. api.gen.go is generated by `pnpm codegen`;
// never edit it by hand. Handlers translate HTTP to domain calls and map
// domain sentinel errors to status codes here, and only here.
package api

import (
	"context"
	"net/http"
)

// Server implements StrictServerInterface.
type Server struct {
	// Version is reported by GET /api/v0/health.
	Version string
}

var _ StrictServerInterface = (*Server)(nil)

// Handler returns the API routes, mounted under /api/ on the dashboard host.
func (s *Server) Handler() http.Handler {
	return Handler(NewStrictHandler(s, nil))
}

// GetHealth reports that the API is serving requests.
func (s *Server) GetHealth(context.Context, GetHealthRequestObject) (GetHealthResponseObject, error) {
	return GetHealth200JSONResponse{Status: HealthStatusOk, Version: s.Version}, nil
}
